import{ITEM_TEMPLATES,validateItemRecipe}from'./effect-recipes.js';
export function editItemEffects(api,item,onSave,context){const $=s=>document.querySelector(s),esc=api.esc,r=structuredClone(item.recipe||ITEM_TEMPLATES.potion),select=(id,rows,v)=>`<select id="${id}">${rows.map(x=>{const[k,label]=Array.isArray(x)?x:[x,x];return`<option value="${k}" ${k===v?'selected':''}>${esc(label)}</option>`}).join('')}</select>`;api.modal('Item effects · '+item.name,`<p class="needs-attention">Effect recipe: saved with the project. This ROM has no verified compiler for these configurable use effects yet. It cannot be installed as working medicine, teaching or ability-changing logic. Existing native items keep working through their native handlers.</p><label>Template${select('recipeTemplate',[['','Custom'],...Object.entries(ITEM_TEMPLATES).map(([k,v])=>[k,v.name])],'')}</label><label>Item type${select('recipeType',[['held','Held item'],['hm','HM'],['tm','TM'],['consumable','Consumable'],['key','Key item']],r.itemType)}</label><label>Reusable${select('recipeReuse',[['no','No · remove after successful use'],['yes','Yes · keep in inventory']],r.reusable?'yes':'no')}</label><p>Price, bag pocket and icon are in the item’s main editor. Availability is assigned by placing the item in a shop, gift, pickup, or Pokémon held-item record; it is not an effect flag.</p><div id="recipeRows"></div><button id="recipeAdd" type="button">＋ Additional effect</button>`,()=>{collect();validateItemRecipe(r);return onSave(r)},'Save effect recipe');function collect(){r.itemType=$('#recipeType').value;r.reusable=$('#recipeReuse').value==='yes';r.effects.forEach((e,i)=>{e.kind=$('#reKind'+i).value;if(['restore','revive'].includes(e.kind))Object.assign(e,{resource:$('#reResource'+i).value,amountMode:$('#reMode'+i).value,amount:+$('#reAmount'+i).value,target:$('#reTarget'+i).value,context:$('#reContext'+i).value});if(e.kind==='teach')e.moveId=+$('#reMove'+i).value;if(['change_ability','buff','status'].includes(e.kind))e.parameter=$('#reParameter'+i).value;});}function draw(){$('#recipeRows').innerHTML=r.effects.map((e,i)=>`<article class="event-step"><label>Effect ${i+1}${select('reKind'+i,['restore','revive','teach','change_ability','buff','status'],e.kind)}</label>${['restore','revive'].includes(e.kind)?`<div class="field-row"><label>Restore${select('reResource'+i,['HP','PP'],e.resource)}</label><label>Amount${select('reMode'+i,[['flat','Flat number'],['percent','Percentage']],e.amountMode)}</label><label>Value<input id="reAmount${i}" type="number" min="1" max="65535" value="${e.amount}"></label></div><label>Target${select('reTarget'+i,[['single','Single Pokémon'],['party','Party']],e.target)}</label><label>Usable${select('reContext'+i,[['both','Battle and overworld'],['battle','In battle'],['overworld','Overworld only']],e.context)}</label>`:e.kind==='teach'?`<label>Move<select id="reMove${i}">${(context?.data?.moves?.length?context.data.moves:[{id:343,name:'Covet'}]).filter(m=>m.id>0).map(m=>`<option value="${m.id}" ${m.id===e.moveId?'selected':''}>${m.id} · ${esc(m.name)}</option>`).join('')}</select></label>`:`<label>Ability / stat / status requirement<input id="reParameter${i}" value="${esc(e.parameter||'')}"></label>`}<button data-re-remove="${i}" type="button">Remove effect</button></article>`).join('');r.effects.forEach((e,i)=>{$('#reKind'+i).onchange=()=>{const next=$('#reKind'+i).value;$('#reKind'+i).value=e.kind;collect();r.effects[i]=next==='teach'?{kind:next,moveId:343}:['restore','revive'].includes(next)?{kind:next,resource:'HP',amountMode:next==='revive'?'percent':'flat',amount:next==='revive'?50:20,target:'single',context:'both'}:{kind:next,parameter:''};draw()}});document.querySelectorAll('[data-re-remove]').forEach(b=>b.onclick=()=>{collect();r.effects.splice(+b.dataset.reRemove,1);draw()});}draw();$('#recipeTemplate').onchange=()=>{const t=ITEM_TEMPLATES[$('#recipeTemplate').value];if(!t)return;Object.assign(r,structuredClone(t));$('#recipeType').value=r.itemType;$('#recipeReuse').value=r.reusable?'yes':'no';draw()};$('#recipeAdd').onclick=()=>{collect();if(r.effects.length>=32)throw Error('Use up to 32 effects.');r.effects.push({kind:'restore',resource:'HP',amountMode:'flat',amount:20,target:'single',context:'both'});draw()};}
